import{_ as t,o as n,c as a,a2 as o}from"./chunks/framework.ClZ-_3DU.js";const p=JSON.parse('{"title":"Brand","description":"","frontmatter":{},"headers":[],"relativePath":"docs/brand.md","filePath":"docs/brand.md"}'),s={name:"docs/brand.md"};function r(i,e,d,h,l,u){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="brand" tabindex="-1">Brand <a class="header-anchor" href="#brand" aria-label="Permalink to &quot;Brand&quot;">​</a></h1><p>Poulpy is a reversible plush octopus: blue and smiling on one side, grumpy on the other. In the app the grumpy side is ember, from burnt orange to red. <strong>The side is the status</strong> (are you keeping your plan?) <strong>and the shade is the feeling</strong> (what just happened). The full brand book, with the logo, colours and every drawing, is on the site&#39;s Brand book page, and <a href="./brand-decisions">Brand decisions</a> traces what was decided and why.</p><h2 id="character-rules" tabindex="-1">Character rules <a class="header-anchor" href="#character-rules" aria-label="Permalink to &quot;Character rules&quot;">​</a></h2><ul><li><strong>Grumpy is comic, never guilt.</strong> No &quot;you failed&quot;, no streak-loss alarms. Even Fuming is a cartoon tantrum.</li><li><strong>Pain and rehab always win.</strong> Someone who logged pain gets the Patched up pose and the blue side for 72 h, never ember.</li><li><strong>One way back, always short.</strong> While Poulpy is ember, the catch-up offered is the shortest workout in the plan, and any finished session flips him straight back.</li><li><strong>Nothing promised, nothing missed.</strong> With no plan, Poulpy stays on the blue side and only reacts to when you last trained.</li><li><strong>Poulpy never lifts his tentacles.</strong> Every pose keeps the plush&#39;s shape and shows the mood with his face, shade, props and small effects.</li><li><strong>At most one notification a day</strong> in Poulpy&#39;s voice, and turning them off keeps the mascot.</li><li><strong>Every line in French and English</strong> from the start.</li></ul><h2 id="moods" tabindex="-1">Moods <a class="header-anchor" href="#moods" aria-label="Permalink to &quot;Moods&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mood</th><th>Side</th><th>When</th></tr></thead><tbody><tr><td>Proud</td><td>Blue</td><td>A personal record, or a full octopus</td></tr><tr><td>Happy</td><td>Blue</td><td>A session done, plan on track; the default</td></tr><tr><td>Recovering</td><td>Blue</td><td>Rest days, the hours after a hard session, pain or rehab days</td></tr><tr><td>Annoyed</td><td>Ember</td><td>Today&#39;s planned session isn&#39;t done and the evening is coming (the grace period)</td></tr><tr><td>Grumpy</td><td>Ember</td><td>A planned session still not done 24 h after its day</td></tr><tr><td>Fuming</td><td>Ember</td><td>Two planned sessions missed</td></tr></tbody></table><h2 id="when-each-drawing-shows" tabindex="-1">When each drawing shows <a class="header-anchor" href="#when-each-drawing-shows" aria-label="Permalink to &quot;When each drawing shows&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What happens</th><th>Mood</th><th>Drawing</th></tr></thead><tbody><tr><td>You finish any session</td><td>Happy</td><td>Flip back to blue with the flip animation; the flip is the reward</td></tr><tr><td>You set a record</td><td>Proud</td><td>Cocky, until the end of the day</td></tr><tr><td>The eighth tentacle lights</td><td>Proud</td><td>Champion, on the end-of-session screen and Home</td></tr><tr><td>A hard session ends (effort 8 or more)</td><td>Recovering</td><td>Exhausted or Side glance, for the rest of the day</td></tr><tr><td>A planned rest day</td><td>Recovering</td><td>Sleeping</td></tr><tr><td>Pain logged, or a rehab session marked too hard</td><td>Recovering</td><td>Patched up</td></tr><tr><td>Mid-set, heavy sets</td><td>Current</td><td>Straining</td></tr><tr><td>A new goal set</td><td>Current</td><td>Standing tall</td></tr><tr><td>Back after a break</td><td>Current</td><td>Shy</td></tr><tr><td>Picking a plan, an unknown exercise</td><td>Current</td><td>Thinking</td></tr><tr><td>Today&#39;s session not done by the evening</td><td>Annoyed</td><td>Annoyed portrait</td></tr><tr><td>A session overdue by 24 h</td><td>Grumpy</td><td>Pouting, with the catch-up offer</td></tr><tr><td>Two sessions missed</td><td>Fuming</td><td>Fuming, with the same catch-up offer</td></tr><tr><td>No plan, 7 days without training</td><td>Happy</td><td>Sleeping</td></tr><tr><td>Loading</td><td></td><td>The loader, Poulpy from above</td></tr></tbody></table><p>Poses marked Current keep whatever mood Poulpy is in. The shared <code>PoulpyCoach</code> decides which drawing shows; <code>PoulpyDrawing</code> names every drawing.</p><h2 id="the-ember-side" tabindex="-1">The ember side <a class="header-anchor" href="#the-ember-side" aria-label="Permalink to &quot;The ember side&quot;">​</a></h2><p>Only a plan can turn Poulpy ember, through its calendar entries. A planned workout placed by hand is a reminder, not a promise, and never counts. See <a href="./brand-decisions">Brand decisions</a>, decision 12.</p><ul><li><strong>Annoyed (the grace period).</strong> From 18:00 on an entry&#39;s day, while it is still planned, until the end of the next day. The entry can still be done the day after: finishing it then marks it done.</li><li><strong>Grumpy.</strong> An entry still planned once the day after its day is over: it is missed.</li><li><strong>Fuming.</strong> Two or more missed entries.</li><li><strong>Any finished session flips him back.</strong> Entries dated on or before the day of the last finished session never count, whatever their status. Finishing the catch-up, a free session or another entry all work.</li><li><strong>Only planned entries count.</strong> Done never counts; a moved entry counts on its new date only; a skipped entry never counts, because skipping is an honest choice and the ember side is for sessions left hanging.</li><li><strong>Rest days never count.</strong> A plan day with no workout has no entry. On a rest day Poulpy sleeps if he is blue and stays ember if he is ember: a rest day doesn&#39;t erase a missed session.</li><li><strong>Pain and rehab win.</strong> For 72 h after pain is logged or a rehab session is marked too hard, Poulpy is blue and Patched up, and entries dated inside those 72 h never count, even afterwards.</li><li><strong>No enrollment, no ember.</strong> Without an active enrollment the blue-side rules apply.</li></ul><p>When several apply, the first wins: pain or rehab, then Fuming, Grumpy, Annoyed, then the blue-side rules.</p><p><strong>The catch-up</strong> is offered with Grumpy and Fuming, and nowhere on the blue side. It is the workout with the shortest estimated duration in the enrolled plan version, the earliest in the plan on a tie. Finishing it flips Poulpy back like any session; it leaves the missed entries as they are, for the person to skip or move. While Annoyed there is no catch-up: today&#39;s entry is the way back.</p><table tabindex="0"><thead><tr><th>Mood</th><th>Title</th><th>Line</th></tr></thead><tbody><tr><td>Annoyed</td><td>Tick tock / Tic tac</td><td>&quot;Today&#39;s {workout} is still waiting. I&#39;m turning a little orange.&quot; / « {workout} t’attend encore aujourd’hui. Je commence à virer à l’orange. »</td></tr><tr><td>Grumpy</td><td>Hmph / Pff</td><td>&quot;{workout} has been waiting since {day}. {minutes} minutes and I flip back, promise.&quot; / « {workout} t’attend depuis {day}. {minutes} minutes et je me retourne, promis. »</td></tr><tr><td>Fuming</td><td>Full lava / Mode lave</td><td>&quot;Sessions slipped by and I&#39;m boiling like a kettle. {minutes} minutes and I&#39;m blue again.&quot; / « Des séances ont filé et je bous comme une bouilloire. {minutes} minutes et je redeviens bleu. »</td></tr><tr><td>Recovering, rest day</td><td>Rest day / Jour de repos</td><td>&quot;No training today. I&#39;m napping too.&quot; / « Pas d’entraînement aujourd’hui. Moi aussi, je fais la sieste. »</td></tr></tbody></table><p>The catch-up button reads &quot;Catch up: {workout}, {minutes} min&quot; / « Rattrapage : {workout}, {minutes} min », with a non-breaking space before the colon. In the Grumpy and Fuming lines, <code>{minutes}</code> is the catch-up&#39;s duration, an ICU plural in the translation files so one minute reads &quot;1 minute&quot;. In the Grumpy line, <code>{workout}</code> and <code>{day}</code> are the oldest missed entry&#39;s: <code>{day}</code> is its weekday while it is less than a week old (&quot;Thursday&quot; / « jeudi »), its date after that (&quot;12 October&quot; / « le 12 octobre »).</p><h2 id="tentacles" tabindex="-1">Tentacles <a class="header-anchor" href="#tentacles" aria-label="Permalink to &quot;Tentacles&quot;">​</a></h2><p>Poulpy&#39;s ring has eight tentacles. Each finished session lights one, and <strong>a lit tentacle never goes dark</strong>: there is no weekly reset, so a quiet month takes nothing away. The eighth makes a <strong>full octopus</strong> (Champion), and the next session starts a new ring. This replaced &quot;eight tentacles a week&quot;; see <a href="./brand-decisions">Brand decisions</a>, decision 11.</p><h2 id="voice" tabindex="-1">Voice <a class="header-anchor" href="#voice" aria-label="Permalink to &quot;Voice&quot;">​</a></h2><p>Poulpy speaks in short first-person lines, warm and a little cheeky: &quot;6 of 8 tentacles lit. One more and I&#39;m doing a little dance.&quot; or &quot;Thursday&#39;s run is still waiting. 20 minutes and I flip back, promise.&quot; He jokes about himself, never about the person. In French he says <em>tu</em>, like a friend, while the rest of the app says <em>vous</em>.</p><h2 id="logo-and-type" tabindex="-1">Logo and type <a class="header-anchor" href="#logo-and-type" aria-label="Permalink to &quot;Logo and type&quot;">​</a></h2><p>The logo is the same drawing as the in-app Poulpy: a front view of the plush with five visible arms and the ember lining peeking out underneath. The app icon is that logo, happy and blue, on Foam (Deep sea for the iOS dark icon), generated by <code>design/build-poulpy.mjs</code>. Headings use Baloo 2, body text Nunito; see the <a href="./design-system">design system</a>.</p><h2 id="ideas-for-later" tabindex="-1">Ideas for later <a class="header-anchor" href="#ideas-for-later" aria-label="Permalink to &quot;Ideas for later&quot;">​</a></h2><ul><li><strong>Shells in the den</strong>: achievements as shells Poulpy collects (first 5 km, 10 sessions, a squat record).</li><li><strong>Colourways</strong>: cosmetic seasonal skins unlocked by milestones.</li><li><strong>Flip the real one</strong>: a widget or morning nudge saying which side the real plush should show today.</li></ul>',24)])])}const g=t(s,[["render",r]]);export{p as __pageData,g as default};
